I am on `react-instantsearch-nextjs` v0.3.14 and I am seeing the same issue but without `DynamicWidgets` - instead I am using the hook `useInfiniteHits` to create a custom hits output like this:

```'use client'
import { useInfiniteHits } from 'react-instantsearch'

export default function InfiniteHits(props: any): JSX.Element {
  const {items, isLastPage, showMore} = useInfiniteHits(props)
  console.log({items})
  
  return (
    <div>
      {items.map((item, index) => (
        <div>
          <a
            href={`/${item.path}`}
            key={index}>
            {item.path}
          </a>
        </div>
      ))}
      {!isLastPage && <button onClick={() => showMore()}>Show More Results</button>}
    </div>
  )
}
```

and my search provider is set up like this
```
'use client';
import { liteClient as algoliasearch } from 'algoliasearch/lite';
import InfiniteHits  from './AlgoliaInfiniteHIts';
import { InstantSearchNext } from 'react-instantsearch-nextjs';

const searchClient = algoliasearch(process.env.NEXT_PUBLIC_ALGOLIA_APPLICATION_ID || '', process.env.NEXT_PUBLIC_ALGOLIA_SEARCH_API_KEY || '');

export function Search() {
  return (
    <InstantSearchNext 
      indexName={process.env.NEXT_PUBLIC_ALGOLIA_INDEX} 
      searchClient={searchClient}
      future={{
        preserveSharedStateOnUnmount: true,
      }}>
      <InfiniteHits/>
    </InstantSearchNext>
  );
}
```
